32	const parseFileContents = async (blob: Blob | File): Promise<string> => {
33	  let contents: string;
34	
35	  if (blob.type === MIME_TYPES.png) {
36	    try {
37	      return await (await import("./image")).decodePngMetadata(blob);
38	    } catch (error: any) {
39	      if (error.message === "INVALID") {
40	        throw new ImageSceneDataError(
41	          "Image doesn't contain scene",
42	          "IMAGE_NOT_CONTAINS_SCENE_DATA",
43	        );
44	      } else {
45	        throw new ImageSceneDataError("Error: cannot restore image");
46	      }
47	    }
48	  } else {
49	    if ("text" in Blob) {
50	      contents = await blob.text();
51	    } else {
52	      contents = await new Promise((resolve) => {
53	        const reader = new FileReader();
54	        reader.readAsText(blob, "utf8");
55	        reader.onloadend = () => {
56	          if (reader.readyState === FileReader.DONE) {
57	            resolve(reader.result as string);
58	          }
59	        };
60	      });
61	    }
62	    if (blob.type === MIME_TYPES.svg) {
63	      try {
64	        return decodeSvgBase64Payload({
65	          svg: contents,
66	        });
67	      } catch (error: any) {
68	        if (error.message === "INVALID") {
